begin;
create table public.marketing_materials(identifier text primary key check(identifier~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),title text not null check(length(btrim(title)) between 1 and 160),description text not null check(length(btrim(description)) between 1 and 1000),category text not null check(category in('Residential Cleaning','Commercial Offices','Property Management / Multifamily','Post-Construction','Airbnb / Short-Term Rentals','Restaurants / Hospitality','Salons / Barbershops','Gyms / Spas','Recording / Production Facilities','Pressure Washing','Luxury Property Care','Other')),internal_notes text check(internal_notes is null or length(internal_notes)<=5000),current_version integer not null default 1 check(current_version>0),is_active boolean not null default true,created_by_user_id uuid references public.user_profiles(id),created_by_name text not null,updated_by_user_id uuid references public.user_profiles(id),updated_by_name text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.marketing_material_versions(id uuid primary key,material_identifier text not null references public.marketing_materials(identifier),version integer not null check(version>0),media_type text not null check(media_type in('image/png','image/jpeg','image/webp','application/pdf')),storage_path text not null unique,original_filename text not null,size_bytes bigint not null check(size_bytes between 1 and 15728640),created_by_user_id uuid references public.user_profiles(id),created_by_name text not null,created_at timestamptz not null default now(),unique(material_identifier,version));
create table public.marketing_material_deliveries(id uuid primary key,material_identifier text not null,material_version integer not null,material_version_id uuid not null references public.marketing_material_versions(id),material_title text not null,media_type text not null,storage_path text not null,original_filename text not null,client_id uuid references public.clients(id) on delete set null,recipient_kind text not null check(recipient_kind in('Existing Client','New Prospect')),recipient_name text not null,recipient_company text,recipient_email text not null,recipient_phone text,subject text not null,message_body text not null,status text not null default 'Prepared' check(status in('Prepared','Sent','Failed')),provider text not null default 'resend',provider_message_id text,failure_reason text,sent_by_user_id uuid not null references public.user_profiles(id),sent_by_name text not null,client_communication_id uuid references public.client_communications(id) on delete set null,attempt_count integer not null default 1 check(attempt_count>0),prepared_at timestamptz not null default now(),sent_at timestamptz,updated_at timestamptz not null default now(),foreign key(material_identifier,material_version) references public.marketing_material_versions(material_identifier,version),constraint marketing_material_delivery_recipient check((recipient_kind='Existing Client' and client_id is not null)or(recipient_kind='New Prospect' and client_id is null and nullif(btrim(recipient_company),'') is not null)));
create index marketing_material_deliveries_created_idx on public.marketing_material_deliveries(prepared_at desc);create index marketing_material_deliveries_client_idx on public.marketing_material_deliveries(client_id)where client_id is not null;create index marketing_material_versions_material_idx on public.marketing_material_versions(material_identifier,version desc);
alter table public.marketing_materials enable row level security;alter table public.marketing_material_versions enable row level security;alter table public.marketing_material_deliveries enable row level security;
revoke all on table public.marketing_materials,public.marketing_material_versions,public.marketing_material_deliveries from public,anon,authenticated;grant select on table public.marketing_materials,public.marketing_material_versions,public.marketing_material_deliveries to authenticated;
create policy "Marketing materials staff read" on public.marketing_materials for select to authenticated using(auth.uid() is not null and public.has_any_role(array['Master Admin','Administrator','Manager','Sales'])and(is_active or public.has_any_role(array['Master Admin','Administrator','Manager'])));
create policy "Marketing material versions staff read" on public.marketing_material_versions for select to authenticated using(auth.uid() is not null and public.has_any_role(array['Master Admin','Administrator','Manager','Sales'])and(public.has_any_role(array['Master Admin','Administrator','Manager'])or exists(select 1 from public.marketing_materials m where m.identifier=material_identifier and m.is_active)or exists(select 1 from public.marketing_material_deliveries d where d.material_version_id=id and d.sent_by_user_id=auth.uid())));
create policy "Marketing delivery management read" on public.marketing_material_deliveries for select to authenticated using(public.has_any_role(array['Master Admin','Administrator','Manager']));create policy "Marketing delivery Sales own read" on public.marketing_material_deliveries for select to authenticated using(public.has_role('Sales')and sent_by_user_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('marketing-materials-private','marketing-materials-private',false,15728640,array['image/png','image/jpeg','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "Marketing material staff read files" on storage.objects for select to authenticated using(bucket_id='marketing-materials-private'and exists(select 1 from public.marketing_material_versions v where v.storage_path=name));create policy "Marketing material management upload files" on storage.objects for insert to authenticated with check(bucket_id='marketing-materials-private'and public.has_any_role(array['Master Admin','Administrator','Manager']));create policy "Marketing material management delete unreferenced files" on storage.objects for delete to authenticated using(bucket_id='marketing-materials-private'and public.has_any_role(array['Master Admin','Administrator','Manager'])and not exists(select 1 from public.marketing_material_versions v where v.storage_path=name));
create function public.register_marketing_material_version(p_identifier text,p_title text,p_description text,p_category text,p_internal_notes text,p_version_id uuid,p_storage_path text,p_original_filename text,p_media_type text,p_size_bytes bigint)returns jsonb language plpgsql security definer set search_path='' as $$declare m public.marketing_materials;v public.marketing_material_versions;profile public.user_profiles;next_version integer;actor text;begin if auth.uid() is null or not public.has_any_role(array['Master Admin','Administrator','Manager'])then raise exception 'Marketing material management denied.' using errcode='42501';end if;select * into profile from public.user_profiles where id=auth.uid()and is_active for share;if not found then raise exception 'An active staff profile is required.' using errcode='42501';end if;actor:=coalesce(nullif(profile.display_name,''),profile.email,profile.role);if p_media_type not in('image/png','image/jpeg','image/webp','application/pdf')or p_size_bytes not between 1 and 15728640 then raise exception 'Invalid marketing material file.';end if;if nullif(btrim(p_title),'')is null or length(btrim(p_title))>160 or nullif(btrim(p_description),'')is null or length(btrim(p_description))>1000 or p_category not in('Residential Cleaning','Commercial Offices','Property Management / Multifamily','Post-Construction','Airbnb / Short-Term Rentals','Restaurants / Hospitality','Salons / Barbershops','Gyms / Spas','Recording / Production Facilities','Pressure Washing','Luxury Property Care','Other')then raise exception 'Invalid marketing material metadata.';end if;select * into m from public.marketing_materials where identifier=p_identifier for update;if found then next_version:=m.current_version+1;update public.marketing_materials set title=btrim(p_title),description=btrim(p_description),category=p_category,internal_notes=nullif(btrim(p_internal_notes),''),current_version=next_version,updated_by_user_id=auth.uid(),updated_by_name=actor,updated_at=now()where identifier=p_identifier returning * into m;else if p_identifier!~'^[a-z0-9]+(?:-[a-z0-9]+)*$'then raise exception 'Invalid stable material identifier.';end if;next_version:=1;insert into public.marketing_materials(identifier,title,description,category,internal_notes,created_by_user_id,created_by_name,updated_by_user_id,updated_by_name)values(p_identifier,btrim(p_title),btrim(p_description),p_category,nullif(btrim(p_internal_notes),''),auth.uid(),actor,auth.uid(),actor)returning * into m;end if;if p_storage_path<>p_identifier||'/v'||next_version||'/'||p_version_id||case p_media_type when'image/png'then'.png'when'image/jpeg'then'.jpg'when'image/webp'then'.webp'else'.pdf'end then raise exception 'Invalid immutable storage path.';end if;insert into public.marketing_material_versions(id,material_identifier,version,media_type,storage_path,original_filename,size_bytes,created_by_user_id,created_by_name)values(p_version_id,p_identifier,next_version,p_media_type,p_storage_path,left(btrim(p_original_filename),255),p_size_bytes,auth.uid(),actor)returning * into v;return jsonb_build_object('material',to_jsonb(m),'version',to_jsonb(v));end$$;
create function public.set_marketing_material_active(p_identifier text,p_is_active boolean)returns public.marketing_materials language plpgsql security definer set search_path='' as $$declare m public.marketing_materials;profile public.user_profiles;actor text;begin if auth.uid()is null or not public.has_any_role(array['Master Admin','Administrator','Manager'])then raise exception 'Marketing material management denied.' using errcode='42501';end if;select * into profile from public.user_profiles where id=auth.uid()and is_active;if not found then raise exception 'An active staff profile is required.' using errcode='42501';end if;actor:=coalesce(nullif(profile.display_name,''),profile.email,profile.role);update public.marketing_materials set is_active=p_is_active,updated_by_user_id=auth.uid(),updated_by_name=actor,updated_at=now()where identifier=p_identifier returning * into m;if not found then raise exception 'Marketing material not found.';end if;return m;end$$;
create function public.update_marketing_material_metadata(p_identifier text,p_title text,p_description text,p_category text,p_internal_notes text)returns public.marketing_materials language plpgsql security definer set search_path='' as $$declare m public.marketing_materials;profile public.user_profiles;actor text;begin if auth.uid()is null or not public.has_any_role(array['Master Admin','Administrator','Manager'])then raise exception 'Marketing material management denied.' using errcode='42501';end if;select * into profile from public.user_profiles where id=auth.uid()and is_active;if not found then raise exception 'An active staff profile is required.' using errcode='42501';end if;if nullif(btrim(p_title),'')is null or length(btrim(p_title))>160 or nullif(btrim(p_description),'')is null or length(btrim(p_description))>1000 or p_category not in('Residential Cleaning','Commercial Offices','Property Management / Multifamily','Post-Construction','Airbnb / Short-Term Rentals','Restaurants / Hospitality','Salons / Barbershops','Gyms / Spas','Recording / Production Facilities','Pressure Washing','Luxury Property Care','Other')then raise exception 'Invalid marketing material metadata.';end if;actor:=coalesce(nullif(profile.display_name,''),profile.email,profile.role);update public.marketing_materials set title=btrim(p_title),description=btrim(p_description),category=p_category,internal_notes=nullif(btrim(p_internal_notes),''),updated_by_user_id=auth.uid(),updated_by_name=actor,updated_at=now()where identifier=p_identifier returning * into m;if not found then raise exception 'Marketing material not found.';end if;return m;end$$;
create function public.prepare_marketing_material_delivery(p_id uuid,p_material_identifier text,p_recipient_kind text,p_client_id uuid,p_recipient_name text,p_recipient_company text,p_recipient_email text,p_recipient_phone text,p_subject text,p_message_body text)returns public.marketing_material_deliveries language plpgsql security definer set search_path='' as $$declare d public.marketing_material_deliveries;c public.clients;profile public.user_profiles;m public.marketing_materials;v public.marketing_material_versions;communication_id uuid;management boolean;begin management:=public.has_any_role(array['Master Admin','Administrator','Manager']);if auth.uid()is null or not(management or public.has_role('Sales'))then raise exception 'Marketing Materials access denied.' using errcode='42501';end if;select * into profile from public.user_profiles where id=auth.uid()and is_active for share;if not found then raise exception 'An active staff profile is required.' using errcode='42501';end if;select * into m from public.marketing_materials where identifier=p_material_identifier and is_active for share;if not found then raise exception 'Select an active marketing material.';end if;select * into v from public.marketing_material_versions where material_identifier=m.identifier and version=m.current_version for share;if not found then raise exception 'The current material version is unavailable.';end if;if p_recipient_kind not in('Existing Client','New Prospect')or nullif(btrim(p_recipient_name),'')is null or length(btrim(p_recipient_name))>160 or nullif(btrim(p_recipient_email),'')is null or length(btrim(p_recipient_email))>320 or btrim(p_recipient_email)!~*'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'then raise exception 'Invalid recipient.';end if;if p_recipient_phone is not null and length(regexp_replace(p_recipient_phone,'[^0-9]','','g'))not between 7 and 15 then raise exception 'A valid phone number is required.';end if;if nullif(btrim(p_subject),'')is null or length(btrim(p_subject))>200 or nullif(btrim(p_message_body),'')is null or length(btrim(p_message_body))>10000 then raise exception 'A valid subject and message are required.';end if;if p_recipient_kind='Existing Client'then select * into c from public.clients where id=p_client_id and archived_at is null for share;if not found then raise exception 'The selected Client is unavailable.';end if;elsif p_client_id is not null or nullif(btrim(p_recipient_company),'')is null then raise exception 'A company or property name is required for a new prospect.';end if;select * into d from public.marketing_material_deliveries where id=p_id for update;if found then if(not management and d.sent_by_user_id<>auth.uid())or d.material_identifier<>p_material_identifier or d.recipient_email<>lower(btrim(p_recipient_email))then raise exception 'Delivery identifier conflict.';end if;return d;end if;if(select count(*)from public.marketing_material_deliveries where sent_by_user_id=auth.uid()and prepared_at>now()-interval'1 hour')>=20 then raise exception 'Marketing material send limit reached. Try again later.';end if;if p_recipient_kind='Existing Client'then insert into public.client_communications(communication_number,client_id,communication_type,channel,direction,status,provider,recipient_email,subject,message_body,sent_by_user_id,sent_by_name,event_key,metadata)values('COMM-'||to_char(now(),'YYYYMMDD')||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),p_client_id,'General','Email','Outbound','Prepared','resend',lower(btrim(p_recipient_email)),btrim(p_subject),btrim(p_message_body),auth.uid(),coalesce(nullif(profile.display_name,''),profile.email,profile.role),'marketing-material:'||p_id,jsonb_build_object('material_identifier',m.identifier,'material_version',v.version,'delivery_id',p_id))returning id into communication_id;end if;insert into public.marketing_material_deliveries(id,material_identifier,material_version,material_version_id,material_title,media_type,storage_path,original_filename,client_id,recipient_kind,recipient_name,recipient_company,recipient_email,recipient_phone,subject,message_body,sent_by_user_id,sent_by_name,client_communication_id)values(p_id,m.identifier,v.version,v.id,m.title,v.media_type,v.storage_path,v.original_filename,p_client_id,p_recipient_kind,btrim(p_recipient_name),nullif(btrim(p_recipient_company),''),lower(btrim(p_recipient_email)),nullif(btrim(p_recipient_phone),''),btrim(p_subject),btrim(p_message_body),auth.uid(),coalesce(nullif(profile.display_name,''),profile.email,profile.role),communication_id)returning * into d;return d;end$$;
create function public.retry_marketing_material_delivery(p_id uuid)returns public.marketing_material_deliveries language plpgsql security definer set search_path='' as $$declare d public.marketing_material_deliveries;management boolean:=public.has_any_role(array['Master Admin','Administrator','Manager']);begin if auth.uid()is null or not(management or public.has_role('Sales'))then raise exception 'Marketing Materials access denied.' using errcode='42501';end if;select * into d from public.marketing_material_deliveries where id=p_id for update;if not found or(not management and d.sent_by_user_id<>auth.uid())then raise exception 'Delivery not found or access denied.';end if;if d.status='Sent'then return d;end if;if d.status<>'Failed'then raise exception 'Only a failed delivery may be retried.';end if;if d.updated_at>now()-interval'30 seconds'then raise exception 'Wait before retrying this delivery.';end if;update public.marketing_material_deliveries set status='Prepared',failure_reason=null,attempt_count=attempt_count+1,updated_at=now()where id=p_id returning * into d;if d.client_communication_id is not null then update public.client_communications set status='Prepared',failure_reason=null where id=d.client_communication_id;end if;return d;end$$;
create function public.mark_marketing_material_delivery(p_id uuid,p_status text,p_provider_message_id text default null,p_failure_reason text default null)returns public.marketing_material_deliveries language plpgsql security definer set search_path='' as $$declare d public.marketing_material_deliveries;management boolean:=public.has_any_role(array['Master Admin','Administrator','Manager']);begin if auth.uid()is null or not(management or public.has_role('Sales'))then raise exception 'Marketing Materials access denied.' using errcode='42501';end if;if p_status not in('Sent','Failed')then raise exception 'Invalid delivery status.';end if;if p_status='Sent'and nullif(btrim(p_provider_message_id),'')is null then raise exception 'Provider message ID is required for a sent delivery.';end if;select * into d from public.marketing_material_deliveries where id=p_id for update;if not found or(not management and d.sent_by_user_id<>auth.uid())then raise exception 'Delivery not found or access denied.';end if;if d.status='Sent'then return d;end if;update public.marketing_material_deliveries set status=p_status,provider_message_id=case when p_status='Sent'then nullif(btrim(p_provider_message_id),'')else provider_message_id end,failure_reason=case when p_status='Failed'then left(coalesce(nullif(btrim(p_failure_reason),''),'Email delivery failed.'),500)end,sent_at=case when p_status='Sent'then now()else sent_at end,updated_at=now()where id=p_id returning * into d;if d.client_communication_id is not null then update public.client_communications set status=p_status,provider_message_id=case when p_status='Sent'then d.provider_message_id else provider_message_id end,failure_reason=d.failure_reason,sent_at=case when p_status='Sent'then d.sent_at else sent_at end where id=d.client_communication_id;end if;return d;end$$;
revoke all on function public.register_marketing_material_version(text,text,text,text,text,uuid,text,text,text,bigint),public.set_marketing_material_active(text,boolean),public.update_marketing_material_metadata(text,text,text,text,text),public.prepare_marketing_material_delivery(uuid,text,text,uuid,text,text,text,text,text,text),public.retry_marketing_material_delivery(uuid),public.mark_marketing_material_delivery(uuid,text,text,text)from public,anon,authenticated;grant execute on function public.register_marketing_material_version(text,text,text,text,text,uuid,text,text,text,bigint),public.set_marketing_material_active(text,boolean),public.update_marketing_material_metadata(text,text,text,text,text),public.prepare_marketing_material_delivery(uuid,text,text,uuid,text,text,text,text,text,text),public.retry_marketing_material_delivery(uuid),public.mark_marketing_material_delivery(uuid,text,text,text)to authenticated;
notify pgrst,'reload schema';commit;
